-- name: CountWorkspaceRowsByTable :one
-- Counts a workspace's rows in every table a GDPR workspace erasure deletes.
-- Used only by tests, which assert that an erasure leaves nothing behind and
-- leaves other workspaces alone. Tables without a workspace_id are counted
-- through the parent ids the test seeded, because the erasure deletes the
-- parents too.
SELECT
  (SELECT COUNT(*) FROM acme_challenges WHERE acme_challenges.workspace_id = sqlc.arg(workspace_id)) AS acme_challenges,
  (SELECT COUNT(*) FROM acme_users WHERE acme_users.workspace_id = sqlc.arg(workspace_id)) AS acme_users,
  (SELECT COUNT(*) FROM apis WHERE apis.workspace_id = sqlc.arg(workspace_id)) AS apis,
  (SELECT COUNT(*) FROM app_build_settings WHERE app_build_settings.workspace_id = sqlc.arg(workspace_id)) AS app_build_settings,
  (SELECT COUNT(*) FROM app_connections WHERE app_connections.workspace_id = sqlc.arg(workspace_id)) AS app_connections,
  (SELECT COUNT(*) FROM app_environment_variables WHERE app_environment_variables.workspace_id = sqlc.arg(workspace_id)) AS app_environment_variables,
  (SELECT COUNT(*) FROM app_regional_settings WHERE app_regional_settings.workspace_id = sqlc.arg(workspace_id)) AS app_regional_settings,
  (SELECT COUNT(*) FROM app_runtime_settings WHERE app_runtime_settings.workspace_id = sqlc.arg(workspace_id)) AS app_runtime_settings,
  (SELECT COUNT(*) FROM app_source_oci WHERE app_source_oci.workspace_id = sqlc.arg(workspace_id)) AS app_source_oci,
  (SELECT COUNT(*) FROM apps WHERE apps.workspace_id = sqlc.arg(workspace_id)) AS apps,
  (SELECT COUNT(*) FROM billing_subscriptions WHERE billing_subscriptions.workspace_id = sqlc.arg(workspace_id)) AS billing_subscriptions,
  (SELECT COUNT(*) FROM certificates WHERE certificates.workspace_id = sqlc.arg(workspace_id)) AS certificates,
  (SELECT COUNT(*) FROM cilium_network_policies WHERE cilium_network_policies.workspace_id = sqlc.arg(workspace_id)) AS cilium_network_policies,
  (SELECT COUNT(*) FROM cli_sessions WHERE cli_sessions.workspace_id = sqlc.arg(workspace_id)) AS cli_sessions,
  (SELECT COUNT(*) FROM clickhouse_outbox WHERE clickhouse_outbox.workspace_id = sqlc.arg(workspace_id)) AS clickhouse_outbox,
  (SELECT COUNT(*) FROM clickhouse_workspace_settings WHERE clickhouse_workspace_settings.workspace_id = sqlc.arg(workspace_id)) AS clickhouse_workspace_settings,
  (SELECT COUNT(*) FROM compute_signup_credit_claims WHERE compute_signup_credit_claims.workspace_id = sqlc.arg(workspace_id)) AS compute_signup_credit_claims,
  (SELECT COUNT(*) FROM custom_domains WHERE custom_domains.workspace_id = sqlc.arg(workspace_id)) AS custom_domains,
  (SELECT COUNT(*) FROM deployment_connections WHERE deployment_connections.workspace_id = sqlc.arg(workspace_id)) AS deployment_connections,
  (SELECT COUNT(*) FROM deployment_steps WHERE deployment_steps.workspace_id = sqlc.arg(workspace_id)) AS deployment_steps,
  (SELECT COUNT(*) FROM deployment_topology WHERE deployment_topology.workspace_id = sqlc.arg(workspace_id)) AS deployment_topology,
  (SELECT COUNT(*) FROM deployments WHERE deployments.workspace_id = sqlc.arg(workspace_id)) AS deployments,
  (SELECT COUNT(*) FROM device_authorizations WHERE device_authorizations.workspace_id = sqlc.arg(device_authorization_workspace_id)) AS device_authorizations,
  (SELECT COUNT(*) FROM encrypted_keys WHERE encrypted_keys.workspace_id = sqlc.arg(workspace_id)) AS encrypted_keys,
  (SELECT COUNT(*) FROM environments WHERE environments.workspace_id = sqlc.arg(workspace_id)) AS environments,
  (SELECT COUNT(*) FROM flag_overrides WHERE flag_overrides.workspace_id = sqlc.arg(workspace_id)) AS flag_overrides,
  (SELECT COUNT(*) FROM github_app_installations WHERE github_app_installations.workspace_id = sqlc.arg(workspace_id)) AS github_app_installations,
  (SELECT COUNT(*) FROM github_repo_connections WHERE github_repo_connections.workspace_id = sqlc.arg(workspace_id)) AS github_repo_connections,
  (SELECT COUNT(*) FROM horizontal_autoscaling_policies WHERE horizontal_autoscaling_policies.workspace_id = sqlc.arg(workspace_id)) AS horizontal_autoscaling_policies,
  (SELECT COUNT(*) FROM identities WHERE identities.workspace_id = sqlc.arg(workspace_id)) AS identities,
  (SELECT COUNT(*) FROM instances WHERE instances.workspace_id = sqlc.arg(workspace_id)) AS instances,
  (SELECT COUNT(*) FROM key_auth WHERE key_auth.workspace_id = sqlc.arg(workspace_id)) AS key_auth,
  (SELECT COUNT(*) FROM key_migrations WHERE key_migrations.workspace_id = sqlc.arg(workspace_id)) AS key_migrations,
  (SELECT COUNT(*) FROM `keys` WHERE keys.workspace_id = sqlc.arg(workspace_id)) AS key_rows,
  (SELECT COUNT(*) FROM keys_permissions WHERE keys_permissions.workspace_id = sqlc.arg(workspace_id)) AS keys_permissions,
  (SELECT COUNT(*) FROM keys_roles WHERE keys_roles.workspace_id = sqlc.arg(workspace_id)) AS keys_roles,
  (SELECT COUNT(*) FROM limits WHERE limits.workspace_id = sqlc.arg(workspace_id)) AS limits,
  (SELECT COUNT(*) FROM logdrains WHERE logdrains.workspace_id = sqlc.arg(workspace_id)) AS logdrains,
  (SELECT COUNT(*) FROM openapi_specs WHERE openapi_specs.workspace_id = sqlc.arg(workspace_id)) AS openapi_specs,
  (SELECT COUNT(*) FROM permissions WHERE permissions.workspace_id = sqlc.arg(workspace_id)) AS permissions,
  (SELECT COUNT(*) FROM portal_domains WHERE portal_domains.workspace_id = sqlc.arg(workspace_id)) AS portal_domains,
  (SELECT COUNT(*) FROM portal_sessions WHERE portal_sessions.workspace_id = sqlc.arg(workspace_id)) AS portal_sessions,
  (SELECT COUNT(*) FROM portals WHERE portals.workspace_id = sqlc.arg(workspace_id)) AS portals,
  (SELECT COUNT(*) FROM projects WHERE projects.workspace_id = sqlc.arg(workspace_id)) AS projects,
  (SELECT COUNT(*) FROM ratelimit_global_counters WHERE ratelimit_global_counters.workspace_id = sqlc.arg(workspace_id)) AS ratelimit_global_counters,
  (SELECT COUNT(*) FROM ratelimit_namespaces WHERE ratelimit_namespaces.workspace_id = sqlc.arg(workspace_id)) AS ratelimit_namespaces,
  (SELECT COUNT(*) FROM ratelimit_overrides WHERE ratelimit_overrides.workspace_id = sqlc.arg(workspace_id)) AS ratelimit_overrides,
  (SELECT COUNT(*) FROM ratelimits WHERE ratelimits.workspace_id = sqlc.arg(workspace_id)) AS ratelimits,
  (SELECT COUNT(*) FROM roles WHERE roles.workspace_id = sqlc.arg(workspace_id)) AS roles,
  (SELECT COUNT(*) FROM roles_permissions WHERE roles_permissions.workspace_id = sqlc.arg(workspace_id)) AS roles_permissions,
  (SELECT COUNT(*) FROM shared_secrets WHERE shared_secrets.workspace_id = sqlc.arg(workspace_id)) AS shared_secrets,
  (SELECT COUNT(*) FROM unkey_principal_permissions WHERE unkey_principal_permissions.workspace_id = sqlc.arg(workspace_id)) AS unkey_principal_permissions,
  (SELECT COUNT(*) FROM unkey_root_keys WHERE unkey_root_keys.workspace_id = sqlc.arg(workspace_id)) AS unkey_root_keys,
  (SELECT COUNT(*) FROM workspace_billing WHERE workspace_billing.workspace_id = sqlc.arg(workspace_id)) AS workspace_billing,
  (SELECT COUNT(*) FROM workspaces WHERE workspaces.id = sqlc.arg(workspace_id)) AS workspaces,
  (SELECT COUNT(*) FROM `keys` WHERE keys.for_workspace_id = sqlc.arg(for_workspace_id)) AS legacy_root_keys,
  (SELECT COUNT(*) FROM keys_permissions WHERE keys_permissions.key_id = sqlc.arg(legacy_root_key_id)) AS legacy_root_key_permissions,
  (SELECT COUNT(*) FROM connection_app_targets WHERE connection_app_targets.connection_id = sqlc.arg(connection_id)) AS connection_app_targets,
  (SELECT COUNT(*) FROM deployment_connection_app_targets WHERE deployment_connection_app_targets.deployment_id = sqlc.arg(deployment_id)) AS deployment_connection_app_targets,
  (SELECT COUNT(*) FROM frontline_routes WHERE frontline_routes.project_id = sqlc.arg(project_id)) AS frontline_routes;
